import { access } from 'node:fs/promises'
import { join } from 'node:path'
import { z } from 'zod'
import sanitizeHtml from 'sanitize-html'
import { createError, getRouterParam, useRuntimeConfig } from 'nuxt/server'
import type { RequestEvent } from 'nuxt/server'

export const uploadedImageName = /^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}\.webp$/

// This wrapper was generated by the WordPress import and is separate from the editable text.
const bookingBlockPattern = /<p class="post-cta">\s*<a\b[^>]*\bhref="https:\/\/aubadecounselling\.janeapp\.com\/"[^>]*>\s*Book an appointment\s*<\/a>\s*<\/p>/i

export function legacyBookingBlock(html: string) {
  return html.match(bookingBlockPattern)?.[0] ?? ''
}

function isUploadedMediaPath(path: string) {
  return path.startsWith('/media/') && uploadedImageName.test(path.slice('/media/'.length))
}

const articleContent = z.object({
  title: z.string().trim().min(1, 'Enter an article title.').max(220),
  bodyHtml: z.string().max(200_000),
  excerpt: z.string().trim().max(500),
  summary: z.string().trim().max(700),
  coverImage: z.string().refine((path) => {
    return path === ''
      || /^\/images\/[\w-]+\.(?:webp|jpe?g|png)$/i.test(path)
      || isUploadedMediaPath(path)
  }, 'Choose an image from the article editor.'),
  coverImageAlt: z.string().trim().max(250),
  seoTitle: z.string().trim().max(160),
  metaDescription: z.string().trim().max(320)
})

export const createArticleInput = z.object({
  slug: z.string().max(120).regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, 'Use lowercase words separated by hyphens for the URL.'),
  publish: z.boolean(),
  content: articleContent
})

export const updateArticleInput = createArticleInput.omit({ slug: true }).extend({
  revision: z.number().int().nonnegative()
})

export function articleId(event: RequestEvent) {
  const id = Number(getRouterParam(event, 'id'))
  if (!Number.isSafeInteger(id) || id < 1) {
    throw createError({ status: 404, statusText: 'Article not found' })
  }
  return id
}

export async function cleanArticleContent(content: z.infer<typeof articleContent>, publish: boolean) {
  const inlineImages = new Map<string, boolean>()
  const bodyHtml = sanitizeHtml(content.bodyHtml.replace(bookingBlockPattern, ''), {
    allowedTags: ['p', 'br', 'h2', 'h3', 'h4', 'strong', 'em', 's', 'u', 'ul', 'ol', 'li', 'blockquote', 'hr', 'a', 'img'],
    allowedAttributes: { '*': ['style'], 'a': ['href', 'target', 'rel'], 'ol': ['start'], 'img': ['src', 'alt'] },
    allowedStyles: { '*': { 'text-align': [/^(left|center|right)$/] } },
    allowedSchemes: ['https', 'http', 'mailto'],
    allowProtocolRelative: false,
    transformTags: {
      a: sanitizeHtml.simpleTransform('a', { rel: 'noopener noreferrer' }),
      img(tagName, attrs) {
        const src = attrs.src ?? ''
        if (!isUploadedMediaPath(src)) return { tagName, attribs: { src: '', alt: '' } }
        const alt = (attrs.alt ?? '').trim().slice(0, 250)
        inlineImages.set(src, Boolean(alt) && (inlineImages.get(src) ?? true))
        return { tagName, attribs: { src, alt } }
      }
    },
    exclusiveFilter: frame => frame.tag === 'img' && !frame.attribs.src
  })
  if (publish && !sanitizeHtml(bodyHtml, { allowedTags: [] }).replaceAll(/&nbsp;|\s/gi, '')) {
    throw createError({ status: 422, statusText: 'Write the article before publishing.' })
  }
  if (publish && content.coverImage && !content.coverImageAlt) {
    throw createError({ status: 422, statusText: 'Describe the cover image before publishing.' })
  }
  if (publish) {
    if ([...inlineImages.values()].includes(false)) {
      throw createError({ status: 422, statusText: 'Describe each inline image before publishing.' })
    }
    const uploadsDir = useRuntimeConfig().cms.uploadsDir
    const uploadedPaths = new Set([...inlineImages.keys(), ...(isUploadedMediaPath(content.coverImage) ? [content.coverImage] : [])])
    await Promise.all([...uploadedPaths].map(path =>
      access(join(uploadsDir, path.slice('/media/'.length))).catch((error: NodeJS.ErrnoException) => {
        if (error.code === 'ENOENT') {
          throw createError({ status: 422, statusText: 'Upload missing article images again before publishing.' })
        }
        throw error
      })
    ))
  }
  return { ...content, bodyHtml, inlineImages: [...inlineImages.keys()] }
}

export async function parseArticleBody<T extends z.ZodType>(event: RequestEvent, schema: T) {
  const body = await readBoundedBody(event, 1_000_000)
  const result = schema.safeParse(await body.json().catch(() => null))
  if (!result.success) {
    throw createError({ status: 422, statusText: 'Check the article fields and try again.' })
  }
  return result.data
}
